package com.musa.cad;

import android.graphics.Bitmap;
import android.graphics.BitmapFactory;
import android.util.Base64;
import android.widget.ImageView;

final class EmbeddedImages {
    private EmbeddedImages() {}

    private static final String PROFILE = "";
    private static final String SPLASH_REFERENCE = "";
    private static final String ABOUT_REFERENCE = "";

    static void applyProfile(ImageView view) { apply(view, PROFILE); }
    static void applySplashReference(ImageView view) { apply(view, SPLASH_REFERENCE); }
    static void applyAboutReference(ImageView view) { apply(view, ABOUT_REFERENCE); }

    private static void apply(ImageView view, String encoded) {
        if (view == null || encoded == null || encoded.isEmpty()) return;
        try {
            byte[] bytes = Base64.decode(encoded, Base64.DEFAULT);
            Bitmap bitmap = BitmapFactory.decodeByteArray(bytes, 0, bytes.length);
            if (bitmap != null) {
                view.setImageBitmap(bitmap);
                view.setAlpha(1f);
                view.setVisibility(android.view.View.VISIBLE);
            }
        } catch (Throwable ignored) {}
    }
}
